WITH flagged AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC) + INTERVAL '14' DAY THEN 1 ELSE 0 END AS is_new_burst FROM web_events), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY session_id ORDER BY event_time ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT s.id, s.session_id, s.event_type, s.page, s.event_time, s.duration_sec, (SELECT AVG(t2.duration_sec) FROM web_events t2 WHERE t2.session_id = s.session_id) AS avg_web_event_duration_sec FROM sessionized s ORDER BY session_id ASC NULLS LAST, duration_sec ASC;
